	@Test
	void earlyCloseDoesNotLeaveAnOldSnapshotApparentlyCurrent(@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		seedSnapshot(directory);
		Path snapshotDirectory = directory.resolve("join-estimator.rjes");
		assertTrue(Files.isRegularFile(snapshotDirectory.resolve("synopsis-v8.bin")));
		Gate gate = new Gate();
		HeldStore store = new HeldStore(directory, config(), gate);
		SailRepository repository = new SailRepository(store);
		repository.init();
		RuntimeException closeFailure = null;
		try {
			assertTrue(gate.entered.await(10, TimeUnit.SECONDS));
			add(repository, "two");
			try {
				repository.shutDown();
			} catch (RuntimeException failure) {
				closeFailure = failure;
			}
		} finally {
			gate.release.countDown();
		}

		// Verify a copy so the read-only check cannot alter the evidence left by the owner.
		Path copy = directory.resolveSibling(directory.getFileName() + "-snapshot-copy");
		Files.createDirectories(copy);
		Files.copy(snapshotDirectory.resolve("synopsis-v8.bin"), copy.resolve("synopsis-v8.bin"));
		Path marker = snapshotDirectory.resolve("synopsis-v8.rebuild");
		if (Files.exists(marker)) {
			Files.copy(marker, copy.resolve("synopsis-v8.rebuild"));
		}
		try (SketchBasedJoinEstimator verifier = new SketchBasedJoinEstimator((s, p, o, c) -> {
			throw new AssertionError("snapshot verification must not scan the source");
		}, SketchBasedJoinEstimator.Config.defaults())) {
			verifier.setRebuildAllowedSupplier(() -> false);
			verifier.configurePersistence(copy, true);
			if (verifier.isReadyNonBlocking()) {
				assertEquals(2L, verifier.synopsisService().publishedRows(),
						"a reusable snapshot must include the commit made before early close");
			}
		}
		assertEquals(null, closeFailure, "early close must complete without a source-read error");
	}

	@Test
	void frontierRebuildWaitsForOwnerWithoutBlockingAWriter(@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		Gate gate = new Gate();
		HeldStore store = new HeldStore(directory,
				config().setSketchEstimatorEnabled(false)
						.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE)
						.setFrontierSynopsisBudgetBytes(32L * 1024L * 1024L),
				gate);
		SailRepository repository = new SailRepository(store);
		repository.init();
		CompletableFuture<FrontierStatisticsStatus> result = new CompletableFuture<>();
		Thread rebuild = null;
		try {
			assertTrue(gate.entered.await(10, TimeUnit.SECONDS));
			try (SailSink active = store.getBackingStore().getExplicitSailSource().sink(IsolationLevels.NONE)) {
				active.clear();
				assertThrows(SailException.class, store::rebuildFrontierStatistics,
						"an already active write must be rejected before waiting");
				store.getBackingStore().rollback();
			}
			rebuild = startRebuild(store, result);
			awaitBlockedOrDone(rebuild, result);
			assertFalse(result.isDone(), "explicit rebuild must wait for its deferred Frontier owner");
			CompletableFuture<Void> writerDone = new CompletableFuture<>();
			Thread writer = Thread.ofPlatform().start(() -> {
				try {
					add(repository, "writer-while-frontier-waits");
					writerDone.complete(null);
				} catch (Throwable failure) {
					writerDone.completeExceptionally(failure);
				}
			});
			try {
				writerDone.get(10, TimeUnit.SECONDS);
			} finally {
				gate.release.countDown();
				writer.join(TimeUnit.SECONDS.toMillis(20));
				assertFalse(writer.isAlive(), "the writer must finish after the startup gate opens");
			}
			assertEquals(FrontierStatisticsAvailability.READY, result.get(20, TimeUnit.SECONDS).availability());
		} finally {
			gate.release.countDown();
			if (rebuild != null) {
				rebuild.join(TimeUnit.SECONDS.toMillis(20));
			}
			repository.shutDown();
		}
	}

