	private static void awaitFrontierNativeBarrier(Thread worker, CompletableFuture<?> result) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (!result.isDone() && System.nanoTime() < deadline) {
			ThreadInfo info = ManagementFactory.getThreadMXBean().getThreadInfo(worker.threadId(), 50);
			if (info != null && Arrays.stream(info.getStackTrace())
					.anyMatch(frame -> frame.getMethodName()
							.equals("admitFrontierReaders"))
					&& Arrays.stream(info.getStackTrace())
							.anyMatch(frame -> frame.getClassName()
									.contains("StampedLongAdderLockManager")
									&& frame.getMethodName().contains("readLock"))) {
				return;
			}
			Thread.onSpinWait();
		}
		throw new AssertionError("Frontier admission did not reach the held native read barrier");
	}

	@Test
	void snapshotCoordinatesAdmitsReaderBeforeNativeBarrier(@TempDir(cleanup = CleanupMode.NEVER) Path directory)
			throws Exception {
		try (TripleStore triples = new TripleStore(directory.resolve("triples").toFile(),
				new LmdbStoreConfig("spoc,posc"), null)) {
			TxnManager manager = triples.getTxnManager();
			List<TxnManager.Txn> fillers = new ArrayList<>();
			CountDownLatch waitingForSlot = new CountDownLatch(1);
			CountDownLatch resumeAdmission = new CountDownLatch(1);
			CompletableFuture<long[]> coordinates = new CompletableFuture<>();
			Thread reader = null;
			try {
				for (TxnManager.Txn filler : manager.createReadTxnPinnedFamily(TxnManager.POOL_SIZE - 1, () -> 0L)) {
					fillers.add(filler);
				}
				assertEquals(0, manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0));
				manager.beforeBlockingReaderAdmissionForTest = () -> {
					waitingForSlot.countDown();
					try {
						resumeAdmission.await();
					} catch (InterruptedException interrupted) {
						Thread.currentThread().interrupt();
						throw new SailException(interrupted);
					}
				};
				reader = Thread.ofPlatform().start(() -> {
					try {
						coordinates.complete(triples.snapshotCoordinates());
					} catch (Throwable failure) {
						coordinates.completeExceptionally(failure);
					}
				});
				assertTrue(waitingForSlot.await(10, TimeUnit.SECONDS), "the coordinates read must face saturation");
				boolean readBarrierHeld = manager.lockManager().isReaderActive();
				long writeStamp = manager.lockManager().tryWriteLock();
				if (writeStamp != 0L) {
					manager.lockManager().unlockWrite(writeStamp);
				}
				assertFalse(readBarrierHeld, "reader capacity must be reserved before entering the native barrier");
				assertTrue(writeStamp != 0L, "a native writer must proceed while coordinates wait for capacity");
			} finally {
				manager.beforeBlockingReaderAdmissionForTest = null;
				resumeAdmission.countDown();
				for (TxnManager.Txn filler : fillers) {
					filler.close();
				}
				if (reader != null) {
					reader.join(TimeUnit.SECONDS.toMillis(20));
					assertFalse(reader.isAlive(), "the read must finish when capacity is released");
				}
			}
			assertEquals(2, coordinates.get(10, TimeUnit.SECONDS).length);
		}
	}

